8: export const useAuthStore = defineStore('auth', () => {
9:   const user = ref<UserOut | null>(null)
10:   const isAuthenticated = computed(() => user.value !== null)
11:   const ready = ref(false)
12: 
13:   let readyPromise: Promise<void> | null = null
14: 
15:   onAuthLost(() => {
16:     user.value = null
17:   })
18: 
19:   async function fetchMe() {
20:     const { data, error } = await api.GET('/api/auth/me')
21:     if (error || !data) {
22:       // 401 already went through one refresh attempt in the client middleware.
23:       user.value = null
24:       return
25:     }
26:     user.value = data
27:   }
28: 
29:   /** Restore the session once on startup; guards await this. */
30:   function init(): Promise<void> {
31:     readyPromise ||= fetchMe().finally(() => {
32:       ready.value = true
33:     })
34:     return readyPromise
35:   }
36: 
37:   async function login(login: string, password: string) {
38:     const { data, error } = await api.POST('/api/auth/login', {
39:       body: { login, password },
40:     })
41:     if (error || !data) throw new Error(extractError(error, 'Login failed'))
42:     // Tokens stay in cookies; only the user profile is kept in memory.
43:     user.value = data.user
44:   }
45: 
46:   async function register(username: string, email: string, password: string) {
47:     const { data, error } = await api.POST('/api/auth/register', {
48:       body: { username, email, password },
49:     })
50:     if (error || !data) throw new Error(extractError(error, 'Registration failed'))
51:     user.value = data.user
52:   }
53: 
54:   async function refresh() {
55:     const { error } = await api.POST('/api/auth/refresh', {
56:       body: { refresh_token: '' },
57:     })
58:     if (error) {
59:       user.value = null
60:       throw new Error(extractError(error, 'Session expired'))
61:     }
62:     await fetchMe()
63:   }
64: 
65:   async function logout() {
66:     try {
67:       await api.POST('/api/auth/logout')
68:     } catch {
69:       // Clear local state even if the server call fails.
70:     }
71:     user.value = null
72:   }
73: 
